<?php
use App\Http\Controllers\ApplicationController; use App\Http\Controllers\AuthController; use App\Http\Controllers\DashboardController; use App\Http\Controllers\FinanceController; use App\Http\Controllers\RegistrationController; use App\Http\Controllers\TranscriptController; use Illuminate\Support\Facades\Route;
Route::redirect('/','/dashboard');
Route::middleware('guest')->group(function (): void { Route::get('/login',[AuthController::class,'loginForm'])->name('login'); Route::post('/login',[AuthController::class,'login']); Route::get('/register',[AuthController::class,'registerForm'])->name('register'); Route::post('/register',[AuthController::class,'register']); });
Route::middleware('auth')->group(function (): void { Route::get('/dashboard',DashboardController::class)->name('dashboard'); Route::get('/applications',[ApplicationController::class,'index'])->name('applications.index'); Route::post('/applications',[ApplicationController::class,'store'])->name('applications.store'); Route::patch('/applications/{application}',[ApplicationController::class,'update'])->name('applications.update'); Route::post('/applications/{application}/documents',[ApplicationController::class,'upload'])->name('applications.documents.store'); Route::get('/application-documents/{document}',[ApplicationController::class,'download'])->name('applications.documents.download'); Route::post('/applications/{application}/submit',[ApplicationController::class,'submit'])->name('applications.submit'); Route::post('/applications/{application}/reviews',[ApplicationController::class,'review'])->name('applications.review'); Route::post('/applications/{application}/decision',[ApplicationController::class,'decide'])->name('applications.decide'); Route::post('/applications/{application}/response',[ApplicationController::class,'respond'])->name('applications.respond'); Route::get('/registration',[RegistrationController::class,'index'])->name('registration.index'); Route::post('/registration',[RegistrationController::class,'store'])->name('registration.store'); Route::get('/finance',[FinanceController::class,'index'])->name('finance.index'); Route::post('/locale',[AuthController::class,'locale'])->name('locale'); Route::post('/logout',[AuthController::class,'logout'])->name('logout'); });
Route::get('/payments/sandbox/{reference}',fn(string $reference)=>response()->view('sandbox-payment',compact('reference')))->name('payments.sandbox');
Route::get('/transcripts/verify/{token}',[TranscriptController::class,'verify'])->name('transcripts.verify');
Route::post('/transcripts/{person}',[TranscriptController::class,'issue'])->middleware('auth')->name('transcripts.issue');
